import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, uv, mul, vec2, time } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  // Geometry – modest size for a feature row
  const geometry = new ctx.THREE.PlaneGeometry(1.5, 0.5, 64, 64);
  const material = new MeshStandardNodeMaterial();
  material.oughness = 0.6;
  material.metalness = 0.2;

  // Load textures (image and depth map) asynchronously, apply when ready
  let colorTex = null;
  let depthTex = null;

  ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      colorTex = tex;
      material.map = tex;
      material.needsUpdate = true;
    })
    .catch(() => {});

  ctx.textureLoader
    .loadTexture(config.depthMapUrl)
    .then((dtex) => {
      depthTex = dtex;
      // Displacement node using depth map, subtle strength
      material.displacementNode = texture(dtex).mul(0.08);
      material.needsUpdate = true;
    })
    .catch(() => {});

  const mesh = new ctx.THREE.Mesh(geometry, material);
  group.add(mesh);

  // Apply any cinematic primitives from config
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const handler = ctx.primitives[prim.name];
      if (handler) {
        const handle = handler(group, prim.params || {});
        primitiveHandles.push(handle);
      }
    }
  }

  // Add a subtle parallax primitive if none present
  if (!config.cinematicPrimitives || config.cinematicPrimitives.length === 0) {
    const parallax = ctx.primitives['parallax-scroll'](group, { strength: 0.04 });
    if (parallax) primitiveHandles.push(parallax);
  }

  // Event handlers stored in userData
  group.userData.handlers = {};

  // Hover lift using GSAP rise‑in preset (0.15 scene units)
  group.userData.handlers.hover = () => {
    if (group.userData._hoverTL) group.userData._hoverTL.kill();
    const tl = gsap.timeline();
    tl.to(group.position, {
      y: group.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    group.userData._hoverTL = tl;
  };

  // Click emits navigation event
  group.userData.handlers.click = () => {
    ctx.emit('hub-features.select');
  };

  // Cleanup routine
  group.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose textures if they were loaded
    if (colorTex) colorTex.dispose();
    if (depthTex) depthTex.dispose();

    // Kill GSAP timelines
    if (group.userData._hoverTL) group.userData._hoverTL.kill();

    // Cleanup primitives
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }
  };

  return group;
}
